#!/usr/bin/env node
// Syncs Sources/OpenClawProtocol from the pinned upstream OpenClaw checkout.
//
// Usage:
//   node Scripts/protocol-gen-swift.mjs            # rewrite the vendored/generated files
//   node Scripts/protocol-gen-swift.mjs --check    # exit 1 when any file is stale
//   node Scripts/protocol-gen-swift.mjs --check --allow-missing-upstream
//                                                  # skip (exit 0) when the checkout is absent
//
// Environment:
//   OPENCLAW_UPSTREAM_DIR   upstream OpenClaw git checkout (default: <repo>/.codex/openclaw)
//
// Upstream files are read with `git show <commit>:<path>`, so the checkout may sit on any
// revision (a blob:none partial clone works) as long as the pinned commits are reachable.
import { execFile } from "node:child_process";
import fs from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { promisify } from "node:util";

const execFileAsync = promisify(execFile);

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, "..");
const outDir = path.join(root, "Sources", "OpenClawProtocol");
const upstreamRepoPath = path.resolve(process.env.OPENCLAW_UPSTREAM_DIR ?? path.join(root, ".codex", "openclaw"));
const checkMode = process.argv.includes("--check");
const allowMissingUpstream = process.argv.includes("--allow-missing-upstream");

const upstreamLabel = "OpenClaw 2026.9.6";
const upstreamVersion = "2026.9.6";
const upstreamCommit = "eb377ac59e";
const upstreamCommitFull = "eb377ac59e6c9fd6c7705028034812becf00271b";
// Previous pin (OpenClaw 2026.4.25); used to compute methods that upstream removed since then.
const previousPinCommit = "6b0c72bec8";
const upstreamSwiftRoot = "apps/shared/OpenClawKit/Sources/OpenClawProtocol";

const generatedBanner = `// Generated by Scripts/protocol-gen-swift.mjs from ${upstreamLabel} (${upstreamCommit}) — do not edit by hand`;
const vendoredNote = `// Vendored by Scripts/protocol-gen-swift.mjs from ${upstreamLabel} (${upstreamCommit}) — do not edit by hand`;

// SDK-owned files whose public names upstream must never define (collision guard).
const LOCAL_OWNED_FILES = [
  "AnyCodable.swift",
  "AnyCodable+Accessors.swift",
  "GatewayCompatModels.swift",
  "GatewayErrorDetails+Support.swift",
  "IntentGraphModels.swift",
  "MultimodalModels.swift",
  "WizardHelpers.swift",
];
// Names emitted into GatewayMethodCatalog.swift.
const CATALOG_TYPE_NAMES = [
  "GatewayMethodCatalog",
  "GatewayMethodDescriptor",
  "GatewayEventName",
  "GatewayServerCapabilityName",
  "GatewayClientID",
  "GatewayClientMode",
  "GatewayClientCapability",
];

async function gitShow(commit, relPath) {
  try {
    const { stdout } = await execFileAsync("git", ["show", `${commit}:${relPath}`], {
      cwd: upstreamRepoPath,
      maxBuffer: 64 * 1024 * 1024,
    });
    return stdout;
  } catch (error) {
    const detail = error instanceof Error ? error.message : String(error);
    throw new Error(`Failed to read ${relPath}@${commit} from ${upstreamRepoPath}: ${detail}`);
  }
}

async function upstreamAvailable() {
  try {
    await fs.access(upstreamRepoPath);
    await execFileAsync("git", ["cat-file", "-e", `${upstreamCommit}^{commit}`], { cwd: upstreamRepoPath });
    return true;
  } catch {
    return false;
  }
}

function publicTopLevelNames(source) {
  const re = /^public (?:final class|class|struct|enum|actor|protocol|typealias|let|var|func) (\w+)/gm;
  return new Set([...source.matchAll(re)].map((m) => m[1]));
}

// MARK: - GatewayModels.swift

function transformGatewayModels(body, localNames) {
  const lines = body.split("\n");
  if (!lines[0].startsWith("// Generated by scripts/protocol-gen-swift.ts")) {
    throw new Error("Unexpected upstream GatewayModels.swift banner; review the generator transforms");
  }
  if (lines[1] !== "// swiftlint:disable file_length") {
    throw new Error("Unexpected upstream swiftlint header in GatewayModels.swift");
  }
  // Generated models carry no doc comments and five lines exceed the 160-column lint limit.
  lines[1] = "// swiftlint:disable file_length missing_docs line_length";
  lines.splice(1, 0, vendoredNote);
  let out = lines.join("\n");

  // Our AnyCodable.value is AnySendableValue, not Any: `.value as? T` compiles but always yields nil.
  out = out.replace(/(\w+)\?\.value as\? String\b/g, "$1?.stringValue");
  out = out.replace(/(\w+)\?\.value as\? Bool\b/g, "$1?.boolValue");
  out = out.replace(/(\w+)\?\.value as\? Int\b/g, "$1?.intValue");
  out = out.replace(/(\w+)\?\.value as\? Double\b/g, "$1?.doubleValue");
  out = out.replace(/(\w+)\?\.value as\? \[String: AnyCodable\]/g, "$1?.dictionaryValue");
  out = out.replace(/(\w+)\?\.value as\? \[AnyCodable\]/g, "$1?.arrayValue");
  const leftovers = [...out.matchAll(/^.*\.value (?:as\?|as!|is) .*$/gm)].map((m) => m[0].trim());
  if (leftovers.length > 0) {
    throw new Error(
      `Unhandled AnyCodable \`.value\` cast(s) in GatewayModels.swift (enum-backed AnyCodable needs typed accessors):\n  ${leftovers.join("\n  ")}`,
    );
  }
  for (const constant of ["GATEWAY_PROTOCOL_VERSION", "GATEWAY_MIN_PROTOCOL_VERSION", "GATEWAY_MIN_NODE_PROTOCOL_VERSION"]) {
    if (!new RegExp(`^public let ${constant} = \\d+$`, "m").test(out)) {
      throw new Error(`GatewayModels.swift is missing \`public let ${constant} = <n>\``);
    }
  }
  if (/^import CoreFoundation/m.test(out)) {
    throw new Error("GatewayModels.swift imports CoreFoundation; OpenClawProtocol must stay Foundation-only for Linux");
  }

  const typeNames = new Set([...out.matchAll(/^public (?:struct|enum) (\w+)/gm)].map((m) => m[1]));
  const upstreamNames = publicTopLevelNames(out);
  const collisions = [...localNames].filter((name) => upstreamNames.has(name));
  if (collisions.length > 0) {
    throw new Error(`Upstream GatewayModels.swift now defines SDK-owned names: ${collisions.sort().join(", ")}`);
  }
  return { text: out, typeNames };
}

// MARK: - Companion files

function vendorCompanion(fileName, body, docInsertions) {
  let out = body;
  for (const [pattern, doc] of docInsertions) {
    if (!pattern.test(out)) {
      throw new Error(`${fileName}: expected declaration for doc insertion not found (${pattern})`);
    }
    out = out.replace(pattern, (_match, indent, decl) => `${indent}/// ${doc}\n${indent}${decl}`);
  }
  if (/\.value (?:as\?|as!|is) /.test(out)) {
    throw new Error(`${fileName}: contains AnyCodable \`.value\` casts; port it by hand instead of vendoring`);
  }
  return `${vendoredNote}\n${out}`;
}

// MARK: - GatewayMethodCatalog.swift

function parseMethodRows(src) {
  const start = src.indexOf("export const CORE_GATEWAY_METHOD_SPECS = [");
  const end = src.indexOf("] as const satisfies", start);
  if (start < 0 || end < 0) {
    throw new Error("core-descriptors.ts: CORE_GATEWAY_METHOD_SPECS table not found");
  }
  const block = src.slice(start, end);
  const rows = [];
  const re =
    /\[\s*"([^"]+)",\s*(null|"[^"]*"),\s*"([^"]+)",\s*"([^"]+)"\s*(?:,\s*(CONTROL_PLANE_WRITE|\{[^}]*\}))?\s*,?\s*\]/g;
  for (const m of block.matchAll(re)) {
    const policy = m[5] ?? "";
    rows.push({
      name: m[1],
      family: m[2] === "null" ? null : m[2].slice(1, -1),
      scope: m[3],
      since: m[4],
      advertised: !/advertise:\s*false/.test(policy),
      startup: /startup:\s*true/.test(policy),
      controlPlaneWrite: policy === "CONTROL_PLANE_WRITE" || /controlPlaneWrite:\s*true/.test(policy),
    });
  }
  const expected = (block.match(/^\s*\[\s*$|^\s*\["/gm) ?? []).length;
  if (rows.length !== expected) {
    throw new Error(`core-descriptors.ts: parsed ${rows.length} method rows but found ${expected} row starts`);
  }
  const seen = new Set();
  for (const row of rows) {
    if (seen.has(row.name)) throw new Error(`core-descriptors.ts: duplicate method ${row.name}`);
    seen.add(row.name);
  }
  return rows;
}

function parseStringArray(src, decl, constants = {}) {
  const m = src.match(new RegExp(`${decl}(?::[^=]*)? = \\[([\\s\\S]*?)\\];`));
  if (!m) throw new Error(`missing ${decl}`);
  return [...m[1].matchAll(/"([^"]+)"|(GATEWAY_EVENT_[A-Z0-9_]+)/g)].map((x) => {
    if (x[1]) return x[1];
    if (!constants[x[2]]) throw new Error(`unresolved constant ${x[2]}`);
    return constants[x[2]];
  });
}

function parseConstObject(src, decl) {
  const m = src.match(new RegExp(`export const ${decl} = \\{([\\s\\S]*?)\\} as const;`));
  if (!m) throw new Error(`missing ${decl}`);
  return [...m[1].matchAll(/^\s*([A-Z0-9_]+):\s*"([^"]+)"/gm)].map((x) => [x[1], x[2]]);
}

const SWIFT_RESERVED = new Set([
  "associatedtype", "class", "deinit", "enum", "extension", "func", "import", "init", "inout", "internal", "let",
  "operator", "private", "protocol", "public", "static", "struct", "subscript", "typealias", "var", "break", "case",
  "continue", "default", "defer", "do", "else", "fallthrough", "for", "guard", "if", "in", "repeat", "return",
  "switch", "where", "while", "as", "catch", "false", "is", "nil", "rethrows", "super", "self", "Self", "throw",
  "throws", "true", "try", "Type", "Protocol", "any", "some",
]);

function swiftCase(raw) {
  const normalized = /^[A-Z0-9_]+$/.test(raw) ? raw.toLowerCase() : raw;
  const words = normalized.replace(/[^A-Za-z0-9]+/g, " ").trim().split(/\s+/);
  let s = words
    .map((w, i) => (i === 0 ? w.charAt(0).toLowerCase() + w.slice(1) : w.charAt(0).toUpperCase() + w.slice(1)))
    .join("");
  if (/^\d/.test(s)) s = `_${s}`;
  if (SWIFT_RESERVED.has(s)) s = `\`${s}\``;
  return s;
}

function pascalMethod(name) {
  return name
    .split(/[.\-]/)
    .map((p) => p.charAt(0).toUpperCase() + p.slice(1))
    .join("");
}

const lit = (s) => JSON.stringify(s);

function swiftStringEnum(name, doc, pairs) {
  const seen = new Set();
  const cases = pairs.map(([key, raw]) => {
    let c = swiftCase(key);
    while (seen.has(c)) c += "_";
    seen.add(c);
    return `    /// Wire value \`${raw}\`.\n    case ${c} = ${lit(raw)}`;
  });
  return `/// ${doc}\npublic enum ${name}: String, Codable, Sendable, CaseIterable {\n${cases.join("\n")}\n}\n`;
}

function renderCatalog({ rows, removed, validateRows, events, serverCaps, clientIds, clientModes, clientCaps }) {
  const descriptorLines = rows.map(
    (r) =>
      `        GatewayMethodDescriptor(name: ${lit(r.name)}, family: ${r.family === null ? "nil" : lit(r.family)}, ` +
      `scope: ${lit(r.scope)}, since: ${lit(r.since)}, advertised: ${r.advertised}, startupGated: ${r.startup}, ` +
      `controlPlaneWrite: ${r.controlPlaneWrite}),`,
  );
  const validateCases = validateRows.map(
    (r) => `        case ${lit(r.name)}: _ = try GatewayPayloadCodec.decode(${pascalMethod(r.name)}Params.self, from: payload)`,
  );
  const removedLines = removed.map((name) => `        ${lit(name)},`);
  return `${generatedBanner}
// swiftlint:disable file_length line_length
import Foundation

/// Static metadata for one upstream core gateway method.
public struct GatewayMethodDescriptor: Sendable, Hashable {
    /// Wire method name, for example \`sessions.list\`.
    public let name: String
    /// Upstream handler family (\`nil\` for methods registered outside a family module).
    public let family: String?
    /// Required scope: an operator scope (\`operator.read\`, \`operator.write\`, \`operator.admin\`, ...),
    /// \`node\` for node-role methods, or \`dynamic\` when the handler resolves the scope per request.
    public let scope: String
    /// Upstream release train that introduced the method (\`<=2026.7\` marks the append-only baseline).
    public let since: String
    /// Whether the gateway advertises the method in hello-ok \`features.methods\`.
    public let advertised: Bool
    /// Whether the gateway answers retryable UNAVAILABLE until startup sidecars are ready.
    public let startupGated: Bool
    /// Whether the method is throttled as a control-plane write.
    public let controlPlaneWrite: Bool

    /// Creates a method descriptor.
    /// - Parameters:
    ///   - name: Wire method name.
    ///   - family: Handler family, if any.
    ///   - scope: Required operator scope, \`node\`, or \`dynamic\`.
    ///   - since: Release train that introduced the method.
    ///   - advertised: Whether hello-ok advertises the method.
    ///   - startupGated: Whether the method waits for startup sidecars.
    ///   - controlPlaneWrite: Whether the method is a throttled control-plane write.
    public init(
        name: String,
        family: String? = nil,
        scope: String,
        since: String,
        advertised: Bool = true,
        startupGated: Bool = false,
        controlPlaneWrite: Bool = false
    ) {
        self.name = name
        self.family = family
        self.scope = scope
        self.since = since
        self.advertised = advertised
        self.startupGated = startupGated
        self.controlPlaneWrite = controlPlaneWrite
    }
}

/// Upstream core gateway method catalog pinned to ${upstreamLabel}.
///
/// Generated from \`src/gateway/methods/core-descriptors.ts\`, \`src/gateway/server-methods-list.ts\`,
/// \`src/gateway/events.ts\`, \`packages/gateway-protocol/src/server-capabilities.ts\` and
/// \`packages/gateway-protocol/src/client-info.ts\` at ${upstreamCommit}.
public enum GatewayMethodCatalog {
    /// Upstream release the catalog was generated from.
    public static let upstreamVersion = ${lit(upstreamVersion)}
    /// Upstream commit (abbreviated) the catalog was generated from.
    public static let upstreamCommit = ${lit(upstreamCommit)}
    /// Full upstream commit SHA the catalog was generated from.
    public static let upstreamCommitFull = ${lit(upstreamCommitFull)}

    /// Every core method, in upstream table order.
    public static let descriptors: [GatewayMethodDescriptor] = [
${descriptorLines.join("\n")}
    ]

    /// Descriptor lookup by wire name.
    public static let byName: [String: GatewayMethodDescriptor] = Dictionary(
        uniqueKeysWithValues: descriptors.map { ($0.name, $0) }
    )

    /// Methods known at the previous pin (${previousPinCommit}) that upstream has since removed.
    public static let removedSincePreviousPin: Set<String> = [
${removedLines.join("\n")}
    ]

    /// Decodes \`payload\` into the generated \`<Method>Params\` model when one exists.
    /// - Parameters:
    ///   - method: Wire method name.
    ///   - payload: Request params (\`nil\` is treated as an empty object).
    /// - Returns: \`true\` when a typed params model exists and decoded; \`false\` when none is generated.
    /// - Throws: The decoding error when the payload does not match the typed params model.
    public static func validateParams(method: String, payload: AnyCodable?) throws -> Bool {
        switch method {
${validateCases.join("\n")}
        default: return false
        }
        return true
    }
}

${swiftStringEnum("GatewayEventName", "Server-to-client event names advertised in hello-ok `features.events`.", events.map((e) => [e, e]))}
${swiftStringEnum("GatewayServerCapabilityName", "Stable feature names advertised in hello-ok `features.capabilities`.", serverCaps)}
${swiftStringEnum("GatewayClientID", "Canonical client ids accepted in connect `client.id`.", clientIds)}
${swiftStringEnum("GatewayClientMode", "Coarse client modes accepted in connect `client.mode`.", clientModes)}
${swiftStringEnum("GatewayClientCapability", "Capability flags a client may advertise in connect `caps`.", clientCaps)}`;
}

// MARK: - Main

async function main() {
  if (!(await upstreamAvailable())) {
    const message = `Upstream OpenClaw checkout with ${upstreamCommit} not found at ${upstreamRepoPath} (set OPENCLAW_UPSTREAM_DIR).`;
    if (checkMode && allowMissingUpstream) {
      console.warn(`warning: ${message} Skipping protocol sync check.`);
      return;
    }
    throw new Error(message);
  }

  const localNames = new Set(CATALOG_TYPE_NAMES);
  localNames.add("AnySendableValue");
  for (const file of LOCAL_OWNED_FILES) {
    const source = await fs.readFile(path.join(outDir, file), "utf8").catch(() => null);
    if (source === null) {
      if (file === "GatewayErrorDetails+Support.swift" || file === "WizardHelpers.swift") continue;
      throw new Error(`Missing SDK-owned protocol file ${file}`);
    }
    for (const name of publicTopLevelNames(source)) localNames.add(name);
  }

  const models = transformGatewayModels(await gitShow(upstreamCommit, `${upstreamSwiftRoot}/GatewayModels.swift`), localNames);
  const agentKind = vendorCompanion(
    "AgentSummary+Kind.swift",
    await gitShow(upstreamCommit, `${upstreamSwiftRoot}/AgentSummary+Kind.swift`),
    [[/^(\s*)(public var isSelectableAgent: Bool)/m, "Whether users may select the agent (system agents such as the setup agent are hidden)."]],
  );
  const wake = vendorCompanion(
    "WakeParamsCompatibility.swift",
    await gitShow(upstreamCommit, `${upstreamSwiftRoot}/WakeParamsCompatibility.swift`),
    [[/^(\s*)(public init\(\s*\n\s*mode: AnyCodable,)/m, "Source-compatible initializer from before `sessionKey` was added; targets the default session."]],
  );

  const rows = parseMethodRows(await gitShow(upstreamCommit, "src/gateway/methods/core-descriptors.ts"));
  const eventsSrc = await gitShow(upstreamCommit, "src/gateway/events.ts");
  const eventConsts = Object.fromEntries(
    [...eventsSrc.matchAll(/export const (GATEWAY_EVENT_[A-Z0-9_]+) = "([^"]+)"/g)].map((m) => [m[1], m[2]]),
  );
  const events = parseStringArray(
    await gitShow(upstreamCommit, "src/gateway/server-methods-list.ts"),
    "export const GATEWAY_EVENTS",
    eventConsts,
  );
  const previousMethods = parseStringArray(
    await gitShow(previousPinCommit, "src/gateway/server-methods-list.ts"),
    "const BASE_METHODS",
  );
  const serverCaps = parseConstObject(
    await gitShow(upstreamCommit, "packages/gateway-protocol/src/server-capabilities.ts"),
    "GATEWAY_SERVER_CAPS",
  );
  const clientInfo = await gitShow(upstreamCommit, "packages/gateway-protocol/src/client-info.ts");
  const clientIds = parseConstObject(clientInfo, "GATEWAY_CLIENT_IDS");
  const clientModes = parseConstObject(clientInfo, "GATEWAY_CLIENT_MODES");
  const clientCaps = parseConstObject(clientInfo, "GATEWAY_CLIENT_CAPS");

  const current = new Set(rows.map((r) => r.name));
  const removed = [...new Set(previousMethods)].filter((m) => !current.has(m)).sort();
  const validateRows = rows.filter((r) => models.typeNames.has(`${pascalMethod(r.name)}Params`));

  const catalog = renderCatalog({ rows, removed, validateRows, events, serverCaps, clientIds, clientModes, clientCaps });

  const outputs = {
    "GatewayModels.swift": models.text,
    "AgentSummary+Kind.swift": agentKind,
    "WakeParamsCompatibility.swift": wake,
    "GatewayMethodCatalog.swift": catalog,
  };
  const stale = [];
  for (const [file, text] of Object.entries(outputs)) {
    const dest = path.join(outDir, file);
    const previous = await fs.readFile(dest, "utf8").catch(() => null);
    if (checkMode) {
      if (previous !== text) stale.push(file);
    } else if (previous !== text) {
      await fs.writeFile(dest, text);
    }
  }
  const hiddenCount = rows.filter((r) => !r.advertised).length;
  console.log(
    `${checkMode ? "Checked" : "Synced"} ${Object.keys(outputs).length} files from ${upstreamLabel} (${upstreamCommit}): ` +
      `types=${models.typeNames.size} methods=${rows.length} (hidden=${hiddenCount}) validators=${validateRows.length} ` +
      `events=${events.length} serverCaps=${serverCaps.length} clientIds=${clientIds.length} removed=${removed.length}`,
  );
  if (stale.length > 0) {
    console.error(`Stale protocol files (run \`node Scripts/protocol-gen-swift.mjs\`): ${stale.join(", ")}`);
    process.exit(1);
  }
}

try {
  await main();
} catch (error) {
  console.error(error instanceof Error ? error.message : String(error));
  process.exit(1);
}
